#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    vector<string> alertNames(vector<string>& keyName, vector<string>& keyTime) {
        unordered_map<string, vector<int>> times;
        for (int i = 0; i < (int)keyName.size(); ++i) {
            int minute = stoi(keyTime[i].substr(0, 2)) * 60 +
                         stoi(keyTime[i].substr(3, 2));
            times[keyName[i]].push_back(minute);
        }
        vector<string> ans;
        for (auto& entry : times) {
            auto& v = entry.second;
            sort(v.begin(), v.end());
            for (int i = 2; i < (int)v.size(); ++i) {
                if (v[i] - v[i - 2] <= 60) {
                    ans.push_back(entry.first); break;
                }
            }
        }
        sort(ans.begin(), ans.end());
        return ans;
    }
};
